// node health-lab/tests/engine.mjs
// The browser engine (health-lab/engine.js) must reproduce the Python pipeline on the
// published sample files: counts, windows, coverage, medications and signals
// (expectations: tests/parity.json, generated by python3 -m healthlab.build).
// It also checks the engine never touches the network, and refuses unmarked (real) files.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const lab = path.resolve(here, '..');
const E = createRequire(import.meta.url)('../engine.js');
const meta = JSON.parse(fs.readFileSync(path.join(lab, 'data/meta.json'), 'utf8'));
const expect = JSON.parse(fs.readFileSync(path.join(here, 'parity.json'), 'utf8'));
const BUNDLES = {
  alex: ['alex-apple-health-export.zip'],
  ben: ['ben-apple-health-export.zip', 'ben-blood-pressure-cuff.csv', 'ben-scale.csv', 'ben-clinical-records.json'],
  carmen: ['carmen-clinical-records.json', 'carmen-glucose-sensor.csv'],
  dorothy: ['dorothy-apple-health-export.zip'],
  malformed: ['malformed-export.xml'],
};
let checks = 0;
const eq = (a, b, msg) => { assert.deepEqual(a, b, msg); checks++; };

// 1. no network calls anywhere in the engine source
const src = fs.readFileSync(path.join(lab, 'engine.js'), 'utf8');
for (const bad of ['fetch(', 'XMLHttpRequest', 'WebSocket', 'sendBeacon', 'importScripts(', 'navigator.', 'localStorage', 'indexedDB']) {
  assert.ok(!src.includes(bad), `engine.js must not use ${bad}`); checks++;
}

for (const [bundle, names] of Object.entries(BUNDLES)) {
  const want = expect[bundle];
  const s = new E.Session(meta.import_spec);
  for (const n of names) {
    const r = await E.importBlob(s, new Blob([fs.readFileSync(path.join(lab, 'samples', n))]), n, {});
    assert.ok(!r.refused, `${n} carries the synthetic mark`);
  }
  const res = s.analyze('2026-11-15');
  for (const [f, c] of Object.entries(want.files)) {
    const got = res.files[f];
    eq({ kept: got.kept, duplicate: got.duplicate, rejected: got.rejected, skipped: got.skipped }, c, `${bundle} ${f} counts`);
  }
  eq(res.observations, want.observations, `${bundle} observations`);
  eq(res.workouts, want.workouts, `${bundle} workouts`);
  eq(res.notifications.length, want.notifications, `${bundle} notifications`);
  eq(res.away_days, want.away_days, `${bundle} away days`);
  for (const w of ['90', '365']) {
    for (const [code, x] of Object.entries(want.windows[w])) {
      const g = res.windows[w][code];
      assert.ok(g, `${bundle} ${w} ${code} present`);
      eq([g.status, g.n_prev, g.n_cur], [x.status, x.n_prev, x.n_cur], `${bundle} ${w}-day ${code}`);
      for (const k of ['prev', 'cur']) if (x[k] != null) { assert.ok(Math.abs(g[k] - x[k]) <= Math.pow(10, -meta.import_spec.dec[code]) + 1e-9, `${bundle} ${w} ${code} ${k} ${g[k]} vs ${x[k]}`); checks++; }
    }
    eq(Object.keys(res.windows[w]).sort(), Object.keys(want.windows[w]).sort(), `${bundle} ${w} metrics`);
  }
  eq(Object.fromEntries(res.coverage.map(c => [c.id, c.status])), want.coverage, `${bundle} coverage`);
  eq(Object.fromEntries(res.medications.map(m => [m.name, m.status])), want.medications, `${bundle} medications`);
  eq(res.signals.map(x => [x.kind, x.tier, x.start, x.end]), want.signals, `${bundle} signals`);
}

// 2. an unmarked (real-looking) export is refused by default, accepted only with allowReal
const real = '<?xml version="1.0"?>\n<HealthData locale="en_US">\n<Record type="HKQuantityTypeIdentifierStepCount" sourceName="iPhone" unit="count" startDate="2026-11-12 08:00:00 -0800" endDate="2026-11-12 09:00:00 -0800" value="100"/>\n</HealthData>\n';
let s2 = new E.Session(meta.import_spec);
eq((await E.importBlob(s2, new Blob([real]), 'export.xml', {})).refused, true, 'real file refused');
eq(s2.obs.size, 0, 'nothing parsed from a refused file');
s2 = new E.Session(meta.import_spec);
await E.importBlob(s2, new Blob([real]), 'export.xml', { allowReal: true });
eq(s2.obs.size, 1, 'allowReal (local development only) parses it');

// 3. cancellation stops a streaming import
const s3 = new E.Session(meta.import_spec), ctl = new AbortController(); ctl.abort();
await assert.rejects(E.importBlob(s3, new Blob([fs.readFileSync(path.join(lab, 'samples', 'alex-apple-health-export.zip'))]), 'alex.zip', { signal: ctl.signal }), /cancelled/); checks++;

console.log(`✓ engine parity: ${checks} checks passed`);
